    introDescription: 'La memoria a largo plazo retiene lo que los miembros dicen en las conversaciones, por lo que no llega activada. Una vez activada, cada miembro tiene su propio espacio de memoria aislado y puede revisarlo, editarlo, eliminarlo o desactivarlo por completo en "Mi memoria". Las memorias activas de perfil y preferencias se incluyen en cada turno posterior; los hechos y tareas en curso se recuperan solo cuando la pregunta está relacionada.',
