        sandbox: {
          docker_enabled: 'Permitir el backend del sandbox de Docker. Un docker.sock local equivale a root en el host, así que esto permanece desactivado por defecto. Solo un administrador del sistema puede activarlo; el cambio surte efecto inmediatamente. Actívalo solo en una instalación privada de un solo nodo que monte el socket del daemon o use un endpoint remoto tcp:// protegido por TLS.'
        },
        tenant: {
          max_owned_per_user: 'Número máximo de espacios de trabajo que un no-superusuario puede poseer vía creación de autoservicio. Se lee en cada creación de espacio y surte efecto inmediatamente después de guardar. 0 usa el valor por defecto integrado de 10; un valor negativo desactiva el límite por completo (no recomendado en despliegues públicos).',
          self_service_creation_enabled: 'Si los no-superusuarios pueden crear espacios de trabajo por sí mismos. Cuando está desactivado, los usuarios regulares solo pueden unirse a espacios existentes por invitación; los superusuarios entre espacios permanecen exentos. Surte efecto inmediatamente.',
          default_storage_quota_gb: 'Cuota de almacenamiento por defecto (GB) asignada cuando se crea un nuevo espacio de trabajo, cubriendo vectores, originales, texto, índices y datos relacionados. Se lee solo en el momento de creación — los cambios aplican solo a espacios recién creados y no actualizan retrospectivamente los existentes. 0 o un valor negativo usa el valor por defecto integrado de 10 GB.',
          auto_create_api_key: 'Crea automáticamente una clave de API full_access para un nuevo espacio de trabajo y devuelve su token en texto plano en la respuesta de creación. Usar solo para integraciones que dependen del comportamiento legacy; está desactivado por defecto y se recomienda la creación explícita de claves de API.',
          auto_accept_invitation: 'Cuando está activado, invitar por email a un usuario ya registrado lo añade como miembro inmediatamente en lugar de esperar la confirmación de la bandeja. Cuando está desactivado, el invitado debe aceptar desde su bandeja. Surte efecto inmediatamente.'
        },
